#include "physics/Physics.h"
#include <algorithm>
namespace forge::physics {void PhysicsWorld::clear(){bodies_.clear();}void PhysicsWorld::addBody(const Body&b){bodies_.push_back(b);}void PhysicsWorld::step(float dt){for(auto&b:bodies_)if(b.dynamic){b.velocity.y-=9.81f*dt;b.position+=b.velocity*dt;if(b.position.y<b.halfExtents.y){b.position.y=b.halfExtents.y;b.velocity.y=0;b.grounded=true;}else b.grounded=false;}}std::vector<Collision> PhysicsWorld::collisions()const{std::vector<Collision>r;for(size_t i=0;i<bodies_.size();++i)for(size_t j=i+1;j<bodies_.size();++j){const auto&a=bodies_[i],b=bodies_[j];if(std::abs(a.position.x-b.position.x)<=a.halfExtents.x+b.halfExtents.x&&std::abs(a.position.y-b.position.y)<=a.halfExtents.y+b.halfExtents.y&&std::abs(a.position.z-b.position.z)<=a.halfExtents.z+b.halfExtents.z)r.push_back({a.entityId,b.entityId});}return r;}}
